<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">  --restart</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> always</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> \\ </span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">               # ← Docker restart policy</span></span>
